// Return the latest event per order id to reporting callers.
// Duplicate imports are resolved by highest seq; on equal seq the later
// received event wins. Cancelled orders are dropped only after deduplication,
// so a cancelled event can still supersede an earlier paid one.
export function liveOrders(events) {
  const latest = new Map();
  for (const event of events) {
    const current = latest.get(event.id);
    if (current === undefined || event.seq >= current.seq) {
      latest.set(event.id, event);
    }
  }
  return [...latest.values()].filter(event => event.state !== 'cancelled');
}

