// Return the latest event per (store, order id) to reporting callers.
// Dedupe rule: highest seq wins; on equal seq the later-received event wins
// (input order is arrival order). Cancelled final states are dropped here so
// callers keep the same interface. Input is caller-owned: never mutate it.
//
// Multi-store: the same order id may exist in different stores, so the dedupe
// key is the store plus the id. Events without a store are historical data and
// belong to the 'default' store. Store names and ids are arbitrary non-empty
// strings, so the key must not rely on string concatenation (a separator could
// appear inside either part); a nested Map keyed by store then id is used.
export const DEFAULT_STORE = 'default';

export function storeOf(event) {
  return event.store === undefined ? DEFAULT_STORE : event.store;
}

// Optional `store` filter: when given, only that store's orders are returned.
export function liveOrders(events, store) {
  const latestByStore = new Map();
  for (const event of events) {
    const eventStore = storeOf(event);
    if (store !== undefined && eventStore !== store) continue;
    let latest = latestByStore.get(eventStore);
    if (latest === undefined) {
      latest = new Map();
      latestByStore.set(eventStore, latest);
    }
    const current = latest.get(event.id);
    if (current === undefined || event.seq >= current.seq) {
      latest.set(event.id, event);
    }
  }
  const result = [];
  for (const latest of latestByStore.values()) {
    for (const event of latest.values()) {
      if (event.state !== 'cancelled') result.push(event);
    }
  }
  return result;
}

